class StandardMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        cr, cc = rows // 2, cols // 2
        best = None
        best_dist = float('inf')
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed and not cell.is_flagged:
                    dist = abs(r - cr) + abs(c - cc)
                    if dist < best_dist:
                        best_dist = dist
                        best = (r, c)
        if best:
            return ('reveal', best[0], best[1])
        return ('reveal', 0, 0)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        p = prob_map.get(pos, 0.5)
        is_corner = (r in (0, rows - 1)) and (c in (0, cols - 1))
        is_edge = (r in (0, rows - 1)) or (c in (0, cols - 1))
        edge_bonus = 0.0
        if is_corner:
            edge_bonus = -0.06
        elif is_edge:
            edge_bonus = -0.03
        revealed_neighbors = sum(
            1 for nr, nc in neighbors_of.get(pos, [])
            if grid[nr][nc].is_revealed
        )
        constraint_bonus = -0.01 * revealed_neighbors
        return (p + edge_bonus + constraint_bonus, self._rng.random())

class RippleRevealPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        best = None
        best_score = -1
        candidates = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed and not cell.is_flagged:
                    dist_center = abs(r - rows // 2) + abs(c - cols // 2)
                    score = -dist_center
                    candidates.append((score, self._rng.random(), r, c))
        if candidates:
            candidates.sort(reverse=True)
            _, _, r, c = candidates[0]
            return ("reveal", r, c)
        return ("reveal", rows // 2, cols // 2)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        zero_revealed_neighbors = sum(
            1
            for nr, nc in neighbors_of.get((r, c), [])
            if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines == 0
        )
        adjusted_p = p * (0.85 ** zero_revealed_neighbors)
        return (adjusted_p, -zero_revealed_neighbors, self._rng.random())

