class TelegraphingMines(MineBehavior):
    """
    After each action, any unrevealed, unflagged mine that is adjacent to at
    least one revealed cell gets 'telegraphed': its adjacent_mines count on
    surrounding revealed cells is augmented with a special warning signal.
    Concretely, every revealed cell neighboring a telegraphed mine has its
    adjacent_mines value set to the true count (recomputed fresh each turn),
    and additionally a one-time proximity pulse is applied: if a mine is
    adjacent to a revealed zero-cell, that mine's own grid value is tagged so
    skilled players can pinpoint it.

    The real mechanic: after every action, mines that are 'exposed' (touching
    a revealed cell) have a small chance (expose_drift_prob) to relocate to a
    non-exposed unrevealed cell, simulating mines that 'flee' from known areas
    into the unknown. This makes deduction harder at the frontier but rewards
    players who flag quickly — flagged mines never flee. Adjacency is
    recomputed after any moves so numbers stay accurate.
    """

    DEFAULT_FLEE_PROB = 0.18

    def __init__(self, seed=None, flee_prob=None):
        super().__init__(seed)
        self.flee_prob = flee_prob if flee_prob is not None else self.DEFAULT_FLEE_PROB

    def summary(self):
        return {"flee_prob": self.flee_prob}

    def on_post_action(self, board, game, action):
        rows = board.config.rows
        cols = board.config.cols

        # Build set of unrevealed, non-mine, non-flagged cells (safe havens)
        # and identify 'exposed' mines (adjacent to at least one revealed cell)
        exposed_mines = []
        safe_havens = []

        for r in range(rows):
            for c in range(cols):
                cell = board.grid[r][c]
                if cell.is_mine and not cell.is_flagged and not cell.is_revealed:
                    # Check if adjacent to any revealed cell
                    touches_revealed = any(
                        board.grid[nr][nc].is_revealed
                        for nr, nc in board.neighbors(r, c)
                    )
                    if touches_revealed:
                        exposed_mines.append((r, c))
                elif not cell.is_mine and not cell.is_revealed and not cell.is_flagged:
                    # Check if NOT adjacent to any revealed cell (deep unknown)
                    touches_revealed = any(
                        board.grid[nr][nc].is_revealed
                        for nr, nc in board.neighbors(r, c)
                    )
                    if not touches_revealed:
                        safe_havens.append((r, c))

        if not exposed_mines or not safe_havens:
            return

        moved = False
        # Snapshot to avoid re-processing moved mines
        for src in exposed_mines:
            if self._rng.random() >= self.flee_prob:
                continue
            if not safe_havens:
                break
            # Pick a random safe haven far from revealed cells
            dst = self._rng.choice(safe_havens)
            if board.move_mine(src, dst):
                safe_havens.remove(dst)
                # The old src is now a non-mine unrevealed cell;
                # check if it qualifies as a new safe haven
                r, c = src
                touches_revealed = any(
                    board.grid[nr][nc].is_revealed
                    for nr, nc in board.neighbors(r, c)
                )
                if not touches_revealed:
                    safe_havens.append(src)
                moved = True

        if moved:
            board.recompute_adjacency()

