class FleeMinesFlagFirstAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        flee_prob = 0.18
        try:
            bs = game.behavior_summary()
            params = bs.get("mine_behavior", {}).get("params", {})
            if "flee_prob" in params:
                flee_prob = float(params["flee_prob"])
        except Exception:
            pass

        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            cell = game.get_cell(r, c)
            if cell.is_revealed or cell.is_flagged:
                adjusted[pos] = p
                continue
            touches_revealed = any(
                game.get_cell(nr, nc).is_revealed
                for nr, nc in neighbors_of.get(pos, [])
            )
            if touches_revealed:
                adjusted[pos] = p * (1.0 - flee_prob)
            else:
                n_exposed_neighbors = sum(
                    1
                    for nr, nc in neighbors_of.get(pos, [])
                    if not game.get_cell(nr, nc).is_revealed
                    and not game.get_cell(nr, nc).is_flagged
                    and any(
                        game.get_cell(nnr, nnc).is_revealed
                        for nnr, nnc in neighbors_of.get((nr, nc), [])
                    )
                )
                inflow = 1.0 - (1.0 - flee_prob) ** max(n_exposed_neighbors, 1) if n_exposed_neighbors > 0 else 0.0
                adjusted[pos] = min(1.0, p + (1.0 - p) * inflow * flee_prob * 0.5)
        return adjusted

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        touches_revealed = any(
            game.get_cell(nr, nc).is_revealed
            for nr, nc in neighbors_of.get(pos, [])
        )
        boundary_penalty = 0.05 if touches_revealed else 0.0
        return (p + boundary_penalty, self._rng.random())

