class SectorSumInfo(InfoStrategy):
    """
    Instead of showing the count of adjacent mines, each revealed cell shows
    the total mine count in a larger 5x5 'sector' centered on that cell
    (capped at 9, shown as '9+' equivalent just as '9').
    The player gets a broader area signal rather than exact neighbor count,
    requiring skilled deduction to triangulate mine positions by overlapping
    sector sums — like a blurry integral rather than a sharp local derivative.
    Zero is still blank (sector truly empty), small numbers still constrain,
    but large overlapping numbers require careful subtraction across sectors.
    """

    def encode(self, board, r, c):
        total = 0
        rows = board.config.rows
        cols = board.config.cols
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if board.grid[nr][nc].is_mine:
                        total += 1
        if total == 0:
            return ""
        return str(min(total, 9))

