class SectorSumDifferentialInfo(InfoStrategy):
    """
    Each revealed cell shows the DIFFERENCE between the mine count in its
    immediate 3x3 Moore neighborhood and the mine count in the ring just
    outside (the 5x5 area minus the 3x3 area). A positive number means
    more mines are close; negative means mines are farther out; zero shows
    as blank. Skilled solvers can set up simultaneous equations using
    overlapping cells to triangulate exact mine positions, while random
    agents cannot exploit the differential signal.
    """

    def encode(self, board, r, c):
        rows = board.config.rows
        cols = board.config.cols

        inner_count = 0
        for nr, nc in board.neighbors(r, c):
            if board.grid[nr][nc].is_mine:
                inner_count += 1

        outer_count = 0
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                if abs(dr) <= 1 and abs(dc) <= 1:
                    continue
                nr, nc = r + dr, c + dc
                if board.in_bounds(nr, nc) and board.grid[nr][nc].is_mine:
                    outer_count += 1

        diff = inner_count - outer_count
        if diff == 0:
            return ""
        return str(diff)

class ProgressiveZoneWin(WinCondition):
    """
    The board is divided into a 4x4 grid of zones. The player must clear
    (reveal all safe cells in) each zone before moving to the next zone
    in a fixed order (left-to-right, top-to-bottom). A zone is 'unlocked'
    once the previous zone is cleared. Clicking in a locked zone still works
    but does not count toward progress. This rewards skilled players who
    systematically deduce and clear each sector, while random agents waste
    clicks in locked zones and fail to build the sequential clearing chain.
    """

    ZONE_ROWS = 4
    ZONE_COLS = 4

    def __init__(self, seed=None):
        super().__init__(seed)
        self._total_zones = self.ZONE_ROWS * self.ZONE_COLS

    def _get_zone(self, r, c, rows, cols):
        zone_r = int(r * self.ZONE_ROWS / rows)
        zone_c = int(c * self.ZONE_COLS / cols)
        return zone_r * self.ZONE_COLS + zone_c

    def _zone_safe_cells(self, board, zone_idx):
        rows = board.config.rows
        cols = board.config.cols
        safe = []
        for r in range(rows):
            for c in range(cols):
                if self._get_zone(r, c, rows, cols) == zone_idx:
                    cell = board.grid[r][c]
                    if not cell.is_mine:
                        safe.append((r, c))
        return safe

    def _zone_cleared(self, board, zone_idx):
        safe_cells = self._zone_safe_cells(board, zone_idx)
        if not safe_cells:
            return True
        return all(board.grid[r][c].is_revealed for r, c in safe_cells)

    def _current_required_zone(self, board):
        """Return the index of the first zone that is not yet cleared."""
        for z in range(self._total_zones):
            if not self._zone_cleared(board, z):
                return z
        return self._total_zones  # all zones cleared

    def evaluate(self, board, game, action):
        required = self._current_required_zone(board)
        if required >= self._total_zones:
            return 'won'
        return None

    def summary(self):
        return {
            'zone_rows': self.ZONE_ROWS,
            'zone_cols': self.ZONE_COLS,
            'total_zones': self._total_zones,
        }

