class ProgressiveZoneAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)
        self._ZONE_ROWS = 4
        self._ZONE_COLS = 4

    def _get_zone(self, r, c, rows, cols):
        zone_r = int(r * self._ZONE_ROWS / rows)
        zone_c = int(c * self._ZONE_COLS / cols)
        return zone_r * self._ZONE_COLS + zone_c

    def _current_required_zone(self, game, rows, cols):
        total_zones = self._ZONE_ROWS * self._ZONE_COLS
        for z in range(total_zones):
            zone_has_unrevealed_safe = False
            for r in range(rows):
                for c in range(cols):
                    if self._get_zone(r, c, rows, cols) == z:
                        cell = game.get_cell(r, c)
                        if not cell.is_mine and not cell.is_revealed:
                            zone_has_unrevealed_safe = True
                            break
                if zone_has_unrevealed_safe:
                    break
            if zone_has_unrevealed_safe:
                return z
        return total_zones

    def opening_action(self, game, grid, rows, cols):
        zone_r_size = rows // self._ZONE_ROWS
        zone_c_size = cols // self._ZONE_COLS
        r = zone_r_size // 2
        c = zone_c_size // 2
        return ("reveal", r, c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        required_zone = self._current_required_zone(game, rows, cols)
        r, c = pos
        cell_zone = self._get_zone(r, c, rows, cols)
        p = prob_map.get(pos, 0.5)
        zone_penalty = abs(cell_zone - required_zone)
        return (zone_penalty, p, self._rng.random())

class Radius2MooreNeighborhoodAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        result = []
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        unrevealed_non_mine = [
            (r, c)
            for r in range(rows)
            for c in range(cols)
            if not grid[r][c].is_revealed and (r, c) not in mine_set
        ]
        if not unrevealed_non_mine:
            return prob_map
        config = game.get_config()
        total_mines = config.mine_count
        flagged_count = sum(
            1 for r in range(rows) for c in range(cols)
            if grid[r][c].is_flagged
        )
        known_mines = len(mine_set)
        remaining_mines = total_mines - flagged_count - known_mines
        off_frontier = [
            pos for pos in unrevealed_non_mine
            if pos not in prob_map
        ]
        if off_frontier and remaining_mines >= 0:
            frontier_expected = sum(prob_map.get(pos, 0.0) for pos in unrevealed_non_mine if pos in prob_map)
            off_frontier_mines = max(0.0, remaining_mines - frontier_expected)
            base_prob = off_frontier_mines / len(off_frontier) if off_frontier else 0.0
            base_prob = min(1.0, max(0.0, base_prob))
            updated = dict(prob_map)
            for pos in off_frontier:
                updated[pos] = base_prob
            return updated
        return prob_map
